export function treeTrace(children,root,order='post'){if(!Array.isArray(children)||!['pre','in','post'].includes(order)||!Number.isInteger(root)||root<0||root>=children.length)throw new TypeError('Valid binary tree/root/order required');const stack=[],recorded=[],heights=Array(children.length).fill(null),frames=[],entered=new Set();const save=(active,phase,message)=>frames.push({active,phase,message,stack:[...stack],recorded:[...recorded],heights:[...heights]});save(null,'start','No calls active and no subtree heights known.');function walk(node){if(node===null)return 0;if(!Number.isInteger(node)||node<0||node>=children.length||entered.has(node)||!Array.isArray(children[node])||children[node].length!==2)throw new TypeError('Acyclic non-shared binary tree required');entered.add(node);stack.push(node);if(order==='pre')recorded.push(node);save(node,'enter',`Enter node ${node}; ${order==='pre'?'record it before children.':'child results are not yet known.'}`);const left=walk(children[node][0]);if(order==='in')recorded.push(node);save(node,'middle',`Left subtree of node ${node} returned ${left}; ${order==='in'?'record between its children.':'now explore its right child.'}`);const right=walk(children[node][1]);heights[node]=1+Math.max(left,right);if(order==='post')recorded.push(node);stack.pop();save(node,'return',`Return height ${heights[node]} from node ${node}: 1+max(${left},${right}). ${order==='post'?'Record after both children.':'Recording order does not change this bottom-up height.'}`);return heights[node];}walk(root);return frames;}
export function trieWalk(words,query){if(!Array.isArray(words)||words.some(w=>typeof w!=='string')||typeof query!=='string')throw new TypeError('Strings required');const nodes=[{prefix:'',terminal:false,children:new Map()}];for(const word of words){let node=0;for(const c of word){if(!nodes[node].children.has(c)){nodes[node].children.set(c,nodes.length);nodes.push({prefix:nodes[node].prefix+c,terminal:false,children:new Map()});}node=nodes[node].children.get(c);}nodes[node].terminal=true;}let node=0;const path=[0];for(const c of query){const next=nodes[node].children.get(c);if(next===undefined)return {nodes,path,exists:false,exact:false};node=next;path.push(node);}return {nodes,path,exists:true,exact:nodes[node].terminal};}
export function knapsackTrace(weight,value,capacity,reuse=false){if(!Number.isInteger(weight)||weight<=0||!Number.isInteger(capacity)||capacity<0||capacity>100||!Number.isFinite(value)||value<0)throw new TypeError('Positive weight, bounded capacity and nonnegative value required');const values=Array(capacity+1).fill(0),frames=[{values:[...values],at:null,source:null,message:'Zero items: best value at every allowed capacity is zero.'}];const positions=Array.from({length:Math.max(0,capacity-weight+1)},(_,i)=>reuse?weight+i:capacity-i);for(const at of positions){const source=at-weight,previous=values[at],read=values[source];values[at]=Math.max(previous,value+read);frames.push({values:[...values],at,source,read,message:`At capacity ${at}, read capacity ${source}=${read}; compare skip ${previous} with take ${value}+${read}. Write ${values[at]}.`});}return frames;}
export function lcsTrace(a,b){if(typeof a!=='string'||typeof b!=='string')throw new TypeError('Strings required');const x=[...a],y=[...b],table=Array.from({length:x.length+1},()=>Array(y.length+1).fill(null)),frames=[];for(let i=0;i<=x.length;i++)table[i][0]=0;for(let j=0;j<=y.length;j++)table[0][j]=0;const save=(i,j,dependencies,message)=>frames.push({i,j,dependencies,message,table:table.map(r=>[...r])});save(null,null,[],'An empty prefix has common-subsequence length zero. Interior cells are not computed.');for(let i=1;i<=x.length;i++)for(let j=1;j<=y.length;j++){const equal=x[i-1]===y[j-1],dependencies=equal?[[i-1,j-1]]:[[i-1,j],[i,j-1]];table[i][j]=equal?1+table[i-1][j-1]:Math.max(table[i-1][j],table[i][j-1]);save(i,j,dependencies,equal?`${x[i-1]} matches: 1 + diagonal ${table[i-1][j-1]} = ${table[i][j]}.`:`${x[i-1]} differs from ${y[j-1]}: max(above ${table[i-1][j]}, left ${table[i][j-1]}) = ${table[i][j]}.`);}return frames;}
